# Strict validation: Check that no word in the list is formed by taking another word in the list and simply appending 'S'
words_set = set()
clean_ch18 = []

for word, definition, example in raw_birds_words:
    w = word.upper().strip().replace("-", "").replace(" ", "")
    if w in used_words:
        continue
    if w in words_set:
        continue
    # Enforce quality check: no base+S duplicate!
    if w.endswith('S') and w[:-1] in words_set:
        print(f"Skipping plural duplicate: {w} (base {w[:-1]} already present)")
        continue
    words_set.add(w)
    clean_ch18.append({
        "word": w,
        "definition": definition,
        "example": example
    })

print(f"Total raw words prepared: {len(raw_birds_words)}")
print(f"Total valid unique Ch18 words: {len(clean_ch18)}")

assert len(clean_ch18) >= 364, f"Need at least 364 words, got {len(clean_ch18)}"

with open("scratch/chapter_18_clean_words.json", "w", encoding="utf-8") as f:
    json.dump(clean_ch18, f, indent=2)

print("Successfully generated scratch/chapter_18_clean_words.json!")
